 for ev,el in ET.iterparse(ROOT/path,events=("start","end")):
  tag=el.tag.rsplit("}",1)[-1]
  if ev=="start":
   if tag=="article":is_article=True
   if tag=="front":in_front=True
   if tag=="body":break
  elif in_front:
   if tag=="article-id":
    k=el.get("pub-id-type");ids.setdefault(k,[]).append("".join(el.itertext()))
   elif tag=="article-title":titles.append("".join(el.itertext()))
   elif tag in {"journal-title","publisher-name","volume","issue","fpage","lpage","elocation-id"}:fields.setdefault(tag,[]).append("".join(el.itertext()))
   elif tag=="license":licenses.append({"attributes":dict(el.attrib),"literal":"".join(el.itertext())})
   if tag=="front":in_front=False
 return {"article_container":is_article,"article_ids":ids,"titles":titles,"bibliographic_fields":fields,"license_literals":licenses,
  "body_scientific_content_interpreted":False,"abstract_content_projected":False,"stopped_at_body_start":True}
