TASK = "TASK-016-P7"
DOIS = ["10.1021/acs.jafc.5c06227", "10.1021/acs.jafc.4c03824", "10.1021/acs.jafc.4c00488", "10.1111/tpj.16898"]
PMIDS = dict(zip(DOIS, ["41108262", "38805380", "38557049", "38923617"]))
AT = datetime.datetime.now(datetime.timezone.utc).isoformat()
def digest(p): return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def save(name, obj, jsonl=False):
    p = NS / name
    if p.exists(): raise RuntimeError("immutable output exists: " + str(p))
    value = "".join(json.dumps(x, ensure_ascii=False, sort_keys=True, allow_nan=False) + "\n" for x in obj) if jsonl else json.dumps(obj, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n"
    write(TASK, str(p.relative_to(ROOT)), value)
def pointer(p):
    p = pathlib.Path(p)
    if not p.is_absolute(): p = ROOT / p
    return {"path":str(p.relative_to(ROOT)), "sha256":digest(p), "bytes":p.stat().st_size}
def canon(url):
    p = urllib.parse.urlsplit(url)
    return (p.scheme.lower(), p.netloc.lower(), urllib.parse.unquote(p.path).rstrip("/"), tuple(sorted(urllib.parse.parse_qsl(p.query, keep_blank_values=True))))
def url_projection(url):
    p = urllib.parse.urlsplit(url)
    signed = any(k.lower().startswith(("x-amz-", "x-goog-")) or k.lower() in {"signature", "token"} for k, v in urllib.parse.parse_qsl(p.query))
    return {"url":None if signed else url, "url_sha256":hashlib.sha256(url.encode()).hexdigest(), "host":p.hostname, "path":p.path, "signed_query_redacted":signed}
def DOI_of(row):
    v = urllib.parse.unquote(" ".join(str(row.get(k,"")) for k in ["url","doi","DOI","source_id"])).lower()
    return [d for d in DOIS if d in v or PMIDS[d] in v]
