evidence = []
routes = {}
def add_route(doi,url,kind,origin,field,access):
    if not isinstance(url,str) or not url.startswith(("https://","http://")): return
    key = (doi,url,kind)
    item = routes.setdefault(key,{"DOI":doi,**url_projection(url),"kind":kind,"metadata_access_assertion":access,"evidence":[]})
    item["evidence"].append({"raw_pointer":pointer(origin),"field":field})
def emit(doi,provider,raw,fields):
    evidence.append({"task":TASK,"epoch_id":"SS-E02","DOI":doi,"PMID":PMIDS[doi],"provider":provider,"raw_pointer":pointer(raw),"projection":fields,"scientific_fields_excluded":True})
for row in selected_metadata:
    raw = ROOT/row["path"]
    obj = json.loads(raw.read_bytes())
    host = urllib.parse.urlsplit(row["url"]).hostname
    if host=="api.crossref.org":
        m = obj["message"]; doi = str(m["DOI"]).lower()
        if doi not in DOIS: continue
        fields = {k:m.get(k) for k in ["DOI","title","type","published","URL","license","link","relation","resource","archive"]}
        emit(doi,"Crossref",raw,fields)
        add_route(doi,m.get("URL"),"DOI_resolver",raw,"message.URL","not an open-original assertion")
        add_route(doi,m.get("resource",{}).get("primary",{}).get("URL"),"publisher_landing",raw,"message.resource.primary.URL","not an open-original assertion")
        for i,x in enumerate(m.get("link",[])):
            add_route(doi,x.get("URL"),"declared_publisher_PDF",raw,"message.link/"+str(i),"Crossref VOR link; license/access not open")
    elif host in {"www.ebi.ac.uk","www.ebi.ac.uk:443"}:
        for i,m in enumerate(obj.get("resultList",{}).get("result",[])):
            doi = str(m.get("doi","")).lower()
            if doi not in DOIS: continue
            fields = {k:m.get(k) for k in ["doi","id","pmid","pmcid","title","pubYear","pubTypeList","isOpenAccess","inPMC","inEPMC","fullTextUrlList"]}
            emit(doi,"Europe PMC",raw,fields)
            for j,x in enumerate(m.get("fullTextUrlList",{}).get("fullTextUrl",[])):
                add_route(doi,x.get("url"),"DOI_resolver",raw,"resultList.result/"+str(i)+"/fullTextUrlList/"+str(j),x.get("availability"))
    elif host=="api.openaire.eu":
        for i,m in enumerate(obj.get("results",[])):
            ds = [str(p.get("value","")).lower() for p in m.get("pids",[]) if p.get("scheme")=="doi"]
            for doi in [d for d in DOIS if d in ds]:
                fields = {k:m.get(k) for k in ["id","mainTitle","pids","publicationDate","publisher","type","bestAccessRight","openAccessColor","embargoEndDate","documentationUrls","codeRepositoryUrl","links","green","isGreen"]}
                fields["instances"] = [{k:x.get(k) for k in ["pids","alternateIdentifiers","license","accessRight","type","urls","publicationDate","hostedBy","collectedFrom"] if k in x} for x in m.get("instances",[])]
                emit(doi,"OpenAIRE",raw,fields)
                for j,x in enumerate(m.get("instances",[])):
                    for k,url in enumerate(x.get("urls",[])):
                        kind = "PubMed_bibliographic_record" if "pubmed.ncbi.nlm.nih.gov" in url else "DOI_resolver" if "doi.org/" in url else "unclassified_metadata_locator"
                        add_route(doi,url,kind,raw,"results/"+str(i)+"/instances/"+str(j)+"/urls/"+str(k),x.get("accessRight",{}).get("label","not supplied; metadata landing only"))
                for field in ["documentationUrls","codeRepositoryUrl","links"]:
                    if m.get(field): raise RuntimeError("unhandled OpenAIRE link field must remain pending: "+field)
    elif host=="api.figshare.com":
        records = obj if isinstance(obj,list) else [obj]
        for i,m in enumerate(records):
            doi = str(m.get("resource_doi","")).lower()
            if doi not in DOIS: continue
            fields = {k:m.get(k) for k in ["id","doi","title","resource_doi","resource_title","url","url_public_api","url_public_html","license","is_public","is_embargoed","download_disabled","related_materials"] if k in m}
            fields["references_URL_only"] = [x for x in m.get("references",[]) if isinstance(x,str) and x.startswith(("https://","http://"))]
            fields["files"] = [{k:f.get(k) for k in ["id","name","size","mimetype","download_url","is_link_only"]} for f in m.get("files",[])]
