from pathlib import Path
import json,re
from scripts.operate import write,digest
out=Path("outputs/evaluation/formal-task017-v2")
paths=["outputs/task016-p7/v1/exposure_ledger.jsonl","outputs/task016-p7/v1/governance/prior_exposure_inventory_v4/prior_exposure_rows.jsonl","outputs/task016-p7/v1/governance/P8-H1-H5-20261013/permanent_prior_exposure_supplement.jsonl"]
allowed={"doi","pmcid","pmid","source_id","source","source_group","source_key","closure_tokens","identity_tokens","aliases","publication","article_id","candidate_source_id","reference_source_id","path","source_path"}
def selected(value):
 if isinstance(value,dict):
  return [v if k in allowed else selected(v) for k,v in value.items() if k in allowed or isinstance(v,(dict,list))]
 if isinstance(value,list):return [selected(v) for v in value if isinstance(v,(dict,list))]
 return []
def tokens(value):
 return {x.lower().rstrip(".,;:)") for x in re.findall(r"10\.\d{4,9}/[a-zA-Z0-9._;()/:+-]+|PMC\d+",json.dumps(value,ensure_ascii=False),re.I)}
catalog={};row_counts={}
for name in paths:
 if not Path(name).is_file():continue
 rows=[json.loads(x) for x in Path(name).read_text().splitlines() if x.strip()]
 row_counts[name]=len(rows)
 for row in rows:
  for token in tokens(selected(row)):catalog.setdefault(token,set()).add(name)
rows=json.loads((out/"handoff/source_queue.json").read_text())
matches=0
for row in rows:
 found=sorted(tokens([row.get("doi"),row.get("pmcid")])&set(catalog))
 row["additional_prior_token_matches"]=found
 row["additional_prior_evidence_files"]=sorted({p for x in found for p in catalog[x]})
 if found and row["prior_status"]!="known_development_exposed_exclude":
  row["prior_status"]="prior_record_match_requires_role_disposition"
 matches+=bool(found)
 row["independent_eligible"]=False if row["prior_status"]=="known_development_exposed_exclude" else None
write("TASK-017",str(out/"handoff/source_queue.json"),json.dumps(rows,ensure_ascii=False,indent=2)+"\n")
summary={"metadata_inputs_sha256":{p:digest(p) for p in paths if Path(p).is_file()},"row_counts":row_counts,"catalog_tokens":len(catalog),"candidate_rows_matching_additional_prior":matches,"scientific_content_read":False,"full_project_alias_closure_complete":False,"independent_targets_admitted":0,"prior_match_is_not_automatically_confirmed_scientific_exposure":True}
write("TASK-017",str(out/"additional_prior_screen.json"),json.dumps(summary,ensure_ascii=False,indent=2)+"\n")
# Update the fixed queue table only, preserving all prior caution and blank labels.
p=out/"handoff/README.md";s=p.read_text();s=s[:s.index("| 序号 |")]
s+="补充对照中央曝光账、既有prior v4与4条曝光补记；候选命中"+str(matches)+"条prior记录。命中不自动等于已确认科学曝光，仍逐项处置；未命中也不证明fresh。见additional_prior_screen.json。\n\n| 序号 | DOI/来源ID | 题名（书目信息） | prior初筛 |\n| --- | --- | --- | --- |\n"
for i,r in enumerate(rows,1):
 title=" / ".join(x for x in r["titles"] if x).replace("|","/").replace("\n"," ")
 doi=r["doi"];link=f"[{doi}](https://doi.org/{doi})" if doi else r["candidate_id"]
 s+=f"| {i} | {link} | {title} | {r['prior_status']} |\n"
write("TASK-017",str(p),s)
print(json.dumps(summary,ensure_ascii=False))

