inputs={}
def load(path,jsonl=False):
 p=Path(path)
 inputs[str(p)]={"sha256":digest(p),"bytes":p.stat().st_size,"kind":"structured_input"}
 return [json.loads(x) for x in p.read_text().splitlines() if x.strip()] if jsonl else json.loads(p.read_text())
def save(name,x):
 write("TASK-017-REVIEW",str(OUT/name),json.dumps(x,ensure_ascii=False,indent=2)+"\n")
def normdoi(x):
 if not isinstance(x,str):return None
 x=html.unescape(x).strip().lower()
 x=re.sub(r"^(?:https?://(?:dx\.)?doi\.org/|doi:\s*)","",x)
 return x if x.startswith("10.") else None
def titlekey(x):
 if isinstance(x,list):x=" ".join(str(a) for a in x)
 return "".join(c for c in unicodedata.normalize("NFKC",html.unescape(re.sub("<[^>]+>","",str(x)))).casefold() if c.isalnum())
def canonical(values):
 if isinstance(values,str):values=[values]
 if not isinstance(values,list) or not values:return None,["missing_structure"]
 parts=[];issues=[]
 for value in values:
  mol=Chem.MolFromSmiles(value)
  if mol is None or not mol.GetNumAtoms():return None,["parse_failure"]
  if any(a.GetAtomicNum()==0 or a.GetNumRadicalElectrons() for a in mol.GetAtoms()):issues.append("wildcard_or_radical")
  if any(label=="?" for _,label in Chem.FindMolChiralCenters(mol,includeUnassigned=True)):issues.append("unassigned_stereochemistry")
  for atom in mol.GetAtoms():atom.SetAtomMapNum(0)
  parts.extend(Chem.MolToSmiles(f,isomericSmiles=True) for f in Chem.GetMolFrags(mol,asMols=True))
 return sorted(parts),sorted(set(issues))
def bound_file(obj,kind="integrity_only"):
 if not isinstance(obj,dict) or not obj.get("path"):return None
 p=Path(obj["path"])
 if not p.is_file():return {"path":str(p),"available":False,"reason":"registered_path_missing"}
 h=digest(p)
 expected=obj.get("sha256")
 return {"path":str(p),"available":True,"sha256":h,"expected_sha256":expected,"sha_matched":expected==h if expected else None,"bytes":p.stat().st_size,"kind":kind}
