def canonical(values):
 if isinstance(values,str):values=[values]
 if not isinstance(values,list) or not values:return None,["missing_structure"]
 parts=[];issues=[]
 for value in values:
  mol=Chem.MolFromSmiles(value)
  if mol is None or not mol.GetNumAtoms():return None,["parse_failure"]
  if any(a.GetAtomicNum()==0 or a.GetNumRadicalElectrons() for a in mol.GetAtoms()):issues.append("wildcard_or_radical")
  if any(label=="?" for _,label in Chem.FindMolChiralCenters(mol,includeUnassigned=True)):issues.append("unassigned_stereochemistry")
  for atom in mol.GetAtoms():atom.SetAtomMapNum(0)
  parts.extend(Chem.MolToSmiles(f,isomericSmiles=True) for f in Chem.GetMolFrags(mol,asMols=True))
 return sorted(parts),sorted(set(issues))
