from pathlib import Path
import xml.etree.ElementTree as ET,re,json
p=Path('outputs/task016-p3/v1/reaction_records.jsonl')
print('P3_PROVENANCE')
for i,line in enumerate(p.read_text().splitlines(),1):
 if any(t in line for t in ['P3R-SS01','P3R-SS02','PMC13084081']):
  d=json.loads(line)
  print('LINE',i,'KEYS',list(d))
  for k,v in d.items():
   if not any(t in k for t in ['smiles','signature','atoms','mapped']):
    out=json.dumps(v,ensure_ascii=False)
    print(k,out[:1500])
for label,f,pattern in [('13084081','data/raw/task016-p3/2026-10-07/pmc/03164a6a60b12be3d6e54e6e/fullTextXML.attempt-1',r'RhaT|naringenin|eriodictyol|prunin|UDP-rhamnose'),('12120870','data/raw/task016-p1/2026-10-06/pmc/PMC12120870-v1-0/fullTextXML.attempt-1',r'25a|astragalin|sugar donor|In vitro|in vitro|glycosylation assay|glycosyltransferase assay|1 mM UDP|UDP-glucose')]:
 root=ET.fromstring(Path(f).read_bytes()); parent={c:p for p in root.iter() for c in p}
 print('ARTICLE',label)
 body=root.find('body')
 for e in body.iter('p'):
  if parent.get(e) is not None and parent[e].tag=='caption': continue
  t=' '.join(''.join(e.itertext()).split())
