   ancestor=e; ids=[]
   while ancestor in parent:
    if ancestor.get('id'): ids.append(ancestor.tag+'#'+ancestor.get('id'))
    ancestor=parent[ancestor]
   print('LOC', '/'.join(reversed(ids)),t[:3900])
