source="from pathlib import Path
from collections import Counter
from xml.etree import ElementTree as ET
import hashlib,json,re,copy,html,csv,io,unicodedata
from rdkit import Chem
from rdkit.Chem import Draw,rdMolDescriptors
from scripts.operate import write,digest
O=Path("outputs/evaluation/task017-evidence-completion-20261015");ROOT=Path.cwd()
OLD=Path("outputs/evaluation/task017-materials-preparation-20261013")
def read(p):return json.loads(Path(p).read_text())
def put(n,s):write("TASK-017-PREP",str(O/n),s)
def save(n,o):put(n,json.dumps(o,ensure_ascii=False,indent=2)+"\n")
def link(p,label=None):return "["+(label or Path(p).name)+"]("+str(ROOT/p)+")"
def norm(s):return "".join(x for x in unicodedata.normalize("NFKC",s).casefold() if x.isalnum())
cards=read(OLD/"reaction_cards.json");pdfs={x["pmcid"]:x for x in read(O/"PDF_manifest.json")["files"]};sifiles={x["pmcid"]:x for x in read(O/"SI_manifest.json")["files"]}
targets={x["doi"]:x for x in read(O/"source_targets.json")}
audit=read(O/"ready_context_audit.json");byobject={x["object_id"]:x for x in audit["contexts"]}
C=read(O/"C_evidence_overlay.json");byreaction={x["reaction_id"]:x for x in C["records"]}
SS=read(O/"SS_evidence_overlay.json");bycard={x["card_id"]:x for x in SS["records"]}
gu={x["object_id"]:x for x in read(O/"GuApiGT_compound_mapping.json")}
props=[read(O/"compound_identity"/(x+".json"))["PropertyTable"]["Properties"][0] for x in ["STRUCT-ID-01","STRUCT-ID-02"]]
assert [p["MolecularFormula"] for p in props]==["C22H24O11","C28H34O15"]
for p in props:
 m=Chem.MolFromSmiles(p["SMILES"]);assert rdMolDescriptors.CalcMolFormula(m)==p["MolecularFormula"]
 assert not any(l=="?" for _,l in Chem.FindMolChiralCenters(m,includeUnassigned=True,useLegacyImplementation=False))
assert Chem.MolFromSmiles(props[1]["SMILES"]).HasSubstructMatch(Chem.MolFromSmiles(props[0]["SMILES"]),useChirality=True)
# Compile uniform XML paragraph IDs and exact full-text hashes; do not trust a producer's ordinal convention.
xmls={}
for d,t in targets.items():
 root=ET.fromstring(Path(t["original_xml"]["path"]).read_bytes());rows=[]
 for b in root.iter():
  if b.tag.rsplit("}",1)[-1]!="body":continue
  for p in b.iter():
   if p.tag.rsplit("}",1)[-1]!="p":continue
   text=" ".join("".join(p.itertext()).split())
   rows.append({"ordinal":len(rows)+1,"xml_id":p.get("id"),"text":text,"text_sha256":hashlib.sha256(text.encode()).hexdigest(),"normalized":norm(text)})
 xmls[t["pmcid"]]=rows
def snippets(obj):
 out=[]
 if isinstance(obj,dict):
  for k,v in obj.items():
   if isinstance(v,str) and len(v)>80 and any(w in k.lower() for w in ["excerpt","paragraph_text","full_text","text_excerpt"]):out.append((v,obj.get("text_sha256")))
   elif isinstance(v,(dict,list)):out+=snippets(v)
 elif isinstance(obj,list):
  for v in obj:out+=snippets(v)
 return out
def evidence_for(pmcid,objects):
 rows=xmls[pmcid];selected={}
 for obj in objects:
  for text,h in snippets(obj):
   key=norm(text)
   matches=[p for p in rows if (h and h==p["text_sha256"]) or (len(key)>60 and key in p["normalized"])]
   for p in matches:
    if p["ordinal"] not in selected:
     selected[p["ordinal"]]={k:v for k,v in p.items() if k!="normalized"}
 # Original citations remain available even when producer excerpts were not mechanically resolvable.
 pages=read(O/"articles"/pmcid/"main_pdf_text.json")["pages"]
 for p in selected.values():
  n=norm(p["text"]);prefix=n[:65]
  found=[x["page"] for x in pages if prefix and prefix in norm(x["text"])]
  p["main_PDF_pages"]=found
  p["locator"]="body//p["+str(p["ordinal"])+"]"+(" [XML id="+p["xml_id"]+"]" if p["xml_id"] else "")
 return sorted(selected.values(),key=lambda x:x["ordinal"])
out_of_scope={"HIST-14","HIST-15","HIST-26","HIST-30"}
pending={"HIST-24":"原供体角色已通过Sasaki2015原文§2.5/§3.3补明，但该篇正文PDF及必要SI被出版方403验证拦截，待补文件后再交审。",
         "HIST-27":"原供体角色已通过Sasaki2015原文§2.5/§3.3补明，但该篇正文PDF及必要SI被出版方403验证拦截，待补文件后再交审。",
         "HIST-25":"GuApiGT 9→9a有LC-MS/转化数据，但Fig3b未给9a标准品/NMR标记；不得把整体酶选择性猜成该产品的确定位点/立体。仍缺具体结构鉴定证据。"}
marker={1:"reference_standard",2:"reference_standard",4:"reference_standard",6:"isolated_NMR",7:"reference_standard",9:"LCMS_scope_only",12:"reference_standard",15:"isolated_NMR",24:"isolated_NMR",26:"reference_standard",27:"isolated_NMR",32:"isolated_NMR"}
records=[]
for card in cards:
 cid=card["card_id"];lane="deferred" if cid in pending else "scope_appendix" if cid in out_of_scope else "human_review"
 variants=[]
 for old in card["contexts"]:
  t=targets[old["source_doi"]];pmcid=t["pmcid"]
  obj=byobject.get(old["object_id"]);extra=byreaction.get(old["reaction_id"]);ss=bycard.get(cid)
  structures={k:old[k] for k in ["product_smiles","acceptor_smiles","donor_smiles","reference_precursors"]}
  changes=[];enzyme=None;notes=[]
  if cid=="HIST-02":
   structures=copy.deepcopy(structures)
   structures["acceptor_smiles"]=props[0]["SMILES"];structures["product_smiles"]=props[1]["SMILES"]
   structures["reference_precursors"]=[structures["acceptor_smiles"],structures["donor_smiles"]]
   enzyme="Cm1,2RhaT"
   changes.append({"type":"source_named_compound_graph_correction_proposal","source_CIDs":[147394,442439],"source_paths":[str(O/"compound_identity/STRUCT-ID-01.json"),str(O/"compound_identity/STRUCT-ID-02.json")],"original_formula":["C21H22O11","C27H32O15"],"proposed_formula":["C22H24O11","C28H34O15"],"meaning":"原eriodictyol类图与原文H7Glu/H7Neo不一致；按原文名称/分子式匹配PubChem完整图。纠正提议改变目标结构；旧target及编码保留，不能回写旧评分或变成fresh。","chemical_correctness":None,"human_approved":None})
   notes.append("旧MpRhaT不是已证实的Cm1,2RhaT同义名；这里只给出原文可定位的酶/标准品对应提议，待人工审核。PubChem仅提供化合物图，不证明反应。")
  if cid=="HIST-17":
   enzyme="Cm1,2RhaT";changes.append({"type":"source_enzyme_rebinding_proposal","old_label":"MpRhaT","proposed_label":"Cm1,2RhaT","same_alias_claimed":False,"human_approved":None})
   notes.append("来源SI物理页31–33，Table4/5/6的Cm1,2RhaT、UDP-Rha、N7Glu/N7Neo；旧标签保留，不悄悄替换。")
  if not structures["donor_smiles"] and old["reaction_id"] in ["P3R-C03","P3R-C04","P4R-C01","P4R-C04","P5R-C01","P5R-C02","P6-SS22-corrected"]:
