 if isinstance(obj,dict):
  for k,v in obj.items():
   if isinstance(v,str) and len(v)>80 and (k.lower() in ["text","quote"] or any(w in k.lower() for w in ["excerpt","paragraph_text","full_text","text_excerpt"])):out.append((v,obj.get("text_sha256")))
   elif isinstance(v,(dict,list)):out+=snippets(v)
