def r(p):return json.loads(Path(p).read_text())
records=r(O/"final_decisions.json")["records"];summary=r(O/"summary.json");checks=[];errors=[]
def ck(name,ok,detail=None):
 checks.append({"check":name,"passed":bool(ok),"detail":detail})
 if not ok:errors.append(name)
ck("32 unique cards",len(records)==len({x["card_id"] for x in records})==32)
contexts=[c for row in records for c in row["contexts"]]
ck("34 unique contexts",len(contexts)==len({x["object_id"] for x in contexts})==34)
ck("final decisions conserved",Counter(x["decision"] for x in records)=={"accept":25,"exclude":4,"insufficient":3})
ck("accepted C9 SS16",Counter(x["family_inherited"] for x in records if x["decision"]=="accept")=={"C_formation":9,"sugar_sugar_formation":16})
ck("scope excluded exact",set(x["card_id"] for x in records if x["decision"]=="exclude")=={"HIST-14","HIST-15","HIST-26","HIST-30"})
ck("insufficient exact",set(x["card_id"] for x in records if x["decision"]=="insufficient")=={"HIST-12","HIST-16","HIST-25"})
previous={x["card_id"]:x for x in r(P/"reaction_review_records.json")}
bindings=0;xml_text_checks=0;pdf_page_checks=0;changed=[];source_inputs={};pdf_cache={};xml_cache={}
for row in records:
 ck(row["card_id"]+" attribution",row["authority"]=="agent_delegated" and row["reviewer_type"]=="agent" and row["human_reviewed"] is False and row["human_conclusion"] is None and row["gold"] is None and row["independent_panel_eligible"] is False)
 ck(row["card_id"]+" source reviewer frozen",digest(row["source_decision_file"])==row["source_decision_file_sha256"])
 oldctx={x["object_id"]:x for x in previous[row["card_id"]]["contexts"]}
 for c in row["contexts"]:
  old=oldctx[c["object_id"]]
  ck(c["object_id"]+" original candidate structures preserved",c["original_structure_snapshot"]==old["original_structure_snapshot"] and c["candidate_structures_preserved"]==old["structures_for_human_review"])
  ck(c["object_id"]+" exact formal reference not auto approved",c["exact_formal_reference_ready"] is False)
  if c["target_identity_changed_from_original"]:changed.append(row["card_id"])
  if c["decision"]=="accept":
   ck(c["object_id"]+" accepted evidence gates",c["normalized_gt_step_supported"] and all(c["checks"][key]=="supported" for key in ["real_gt_step","source_match","graph_identity","stereochemistry","donor_identity","assay_boundary","domain_in_scope"]) and c["adopted_normalized_GT_structures"]==old["structures_for_human_review"])
  else:ck(c["object_id"]+" no insufficient/excluded graph admission",c["adopted_normalized_GT_structures"] is None)
  ck(c["object_id"]+" evidence bindings present",bool(c["source_bindings"]))
  for b in c["source_bindings"]:
   bindings+=1;path=Path(b["path"]);h=digest(path)
   ck(c["object_id"]+" binding "+str(bindings)+" source SHA",h==b["sha256"])
   source_inputs[str(path)]={"sha256":h,"bytes":path.stat().st_size}
   page=b.get("physical_page")
   if page is not None and path.suffix.lower()==".pdf":
    if str(path) not in pdf_cache:pdf_cache[str(path)]=fitz.open(path)
    doc=pdf_cache[str(path)];ck(c["object_id"]+" PDF page range "+str(page),1<=page<=len(doc))
    if 1<=page<=len(doc):
     expected=b.get("page_text_sha256",b.get("extracted_text_sha256"))
     if expected:
      pdf_page_checks+=1
      ck(c["object_id"]+" PDF page text "+str(page),hashlib.sha256(doc[page-1].get_text().encode()).hexdigest()==expected)
   if b.get("xml_locator"):
    if str(path) not in xml_cache:
     root=ET.fromstring(path.read_bytes());ps=[]
     for body in root.iter():
      if body.tag.rsplit("}",1)[-1]=="body":ps.extend(p for p in body.iter() if p.tag.rsplit("}",1)[-1]=="p")
     xml_cache[str(path)]=ps
    match=re.search(r"(?:p\[|\)\[)(\d+)\]",b["xml_locator"])
    if match:
     ordinal=int(match.group(1));ps=xml_cache[str(path)];ck(c["object_id"]+" XML ordinal",1<=ordinal<=len(ps))
     expected=b.get("normalized_text_sha256",b.get("paragraph_text_sha256"))
     if expected and 1<=ordinal<=len(ps):
      xml_text_checks+=1;text=" ".join("".join(ps[ordinal-1].itertext()).split())
      ck(c["object_id"]+" XML exact paragraph",hashlib.sha256(text.encode()).hexdigest()==expected)
