  c=row["contexts"][0];b=next(b for b in c["source_bindings"] if b.get("physical_page")==5 and b["path"]==c["primary_PDF"]["path"])
  ck(row["card_id"]+" inaccurate marker claim corrected without altering verdict","未列" in b["claim_zh"] and "claim_before_cross_review_correction" in b and b["decision_changed_by_wording_correction"] is False and c["GuApiGT_binding"]["identification_level"]=="LCMS_only_structure_unresolved")
