protected=r("outputs/evaluation/formal-task017-v2/protected_hashes.json")
allowed={"STATE.md","ARCHITECTURE.md","docs/tasks/TASK-017-independent-c-ss-transfer-benchmark.md"}
legacy=[];drift=[];protected_count=0
for path,meta in protected.items():
 if path in allowed:continue
 if Path(path).name.startswith("._") and not Path(path).is_file():legacy.append(path);continue
 protected_count+=1;expected=meta["sha256"] if isinstance(meta,dict) else meta
 if not Path(path).is_file() or digest(path)!=expected:drift.append(path)
ck("substantive code/scientific inputs protected",not drift,{"checked":protected_count,"drifts":drift,"legacy_AppleDouble_missing":len(legacy)})
oldreport="docs/reports/REPORT-017-evidence-completion-20261015.md"
prevmanifest=r(P/"delivery_manifest.json")["files"]
ck("previous report unchanged",digest(oldreport)==prevmanifest[oldreport]["sha256"])
h=(O/"final_review.html").read_text();bad=[]
for path in re.findall(r"(?:href|src)='([^']+)'",h):
 path=html.unescape(path)
 if not path.startswith(("http:","https:","#")) and not (O/path).is_file():bad.append(path)
for p in [O/"README.md",O/"DECISIONS.md",*list((O/"cards").glob("*.md"))]:
 outside=[];fenced=False
 for line in p.read_text().splitlines():
  if line.startswith("~~~"):fenced=not fenced;continue
  if not fenced:outside.append(line)
 for path in re.findall(r"\]\(([^)\n]+)\)","\n".join(outside)):
  path=path.strip("<>")
  if not path.startswith(("http:","https:","#")):
   target=Path(path) if path.startswith("/") else p.parent/path
   if not target.is_file():bad.append(str(target))
ck("all final review local links resolve",not bad,bad[:8])
script=re.search(r"<script>(.*?)</script>",h,re.S).group(1)
js=subprocess.run(["node","-e","new (require('vm').Script)(process.argv[1]);",script],capture_output=True,text=True)
ck("HTML filter JS syntax and 32 articles",js.returncode==0 and h.count("<article ")==32)
ck("cross review artifact present",Path(O/"cross_review_audit.json").is_file())
ck("old graph diagnostic 34 contexts internally consistent",len(r(O/"graph_consistency_diagnostics.json"))==34 and all(x["non_anomeric_sugar_identity_matches"] and x["product_acceptor_stereo_subgraph_matches"]>0 for x in r(O/"graph_consistency_diagnostics.json")))
