commands=6+sum(e.get("action")=="command_start" and e.get("task","").startswith("TASK-017") for e in events)+2
ck("TASK017 cumulative command budget",commands<=280,{"cumulative":commands,"limit":280,"separate_other_tasks_excluded":True,"legacy_recovery_unwrapped_pwd_and_malformed_help_included":2})
ck("scientific and independent gates not relaxed",summary["scientific_cells"]==summary["fresh_independent_panel_reactions"]==summary["gold_records_produced"]==summary["exact_formal_reference_ready_cards"]==0 and summary["research_run_ready"] is False and summary["release_ready"] is False)
for doc in pdf_cache.values():doc.close()
result={"status":"passed" if not errors else "failed","errors":errors,"checks_count":len(checks),"checks":checks,"source_binding_hashes_checked":bindings,"PDF_page_text_hashes_checked":pdf_page_checks,"XML_paragraph_hashes_checked":xml_text_checks,"frozen_previous_materials_count":len(baseline),"protected_substantive_count":protected_count,"legacy_missing_AppleDouble_sidecar_count":len(legacy),"all_scientific_truth_revalidated_by_this_integrity_check":False,"scientific_adjudication":"three source reviewers plus parent and bounded independent cross-review; not experimental revalidation","browser_full_visual_test":"not_run; source-specific figures visually reviewed, HTML links/JS static verification only","authority":"agent_delegated","human_reviewed":False,"commands_at_verification":commands,"other_concurrent_tasks_excluded_from_task_budget":True}
write("TASK-017-AGENT-REVIEW",str(O/"verification.json"),json.dumps(result,ensure_ascii=False,indent=2)+"\n")
write("TASK-017-AGENT-REVIEW",str(O/"review_source_inputs.json"),json.dumps({"existing_source_inputs":source_inputs,"new_HTTP":0,"new_queries":0,"new_external_source_files":0,"inherited_cumulative_file_count":174,"inherited_cumulative_bytes":155002911,"derived_review_outputs_not_source_intake":True},ensure_ascii=False,indent=2)+"\n")
print(json.dumps({k:v for k,v in result.items() if k!="checks"},ensure_ascii=False))
if errors:raise SystemExit(1)
"
compile(src,'verify','exec')
